#ifndef DUMP_BINARY_WEIGHTS
int init_tinylacelayers(TINYLACELayers *model, const WeightArray *arrays) {
    if (linear_init(&model->lace_pitch_embedding, arrays, "tinylace_pitch_embedding_bias", NULL, NULL,"tinylace_pitch_embedding_weights_float", NULL, NULL, NULL, 301, 4)) return 1;
    if (linear_init(&model->lace_fnet_conv1, arrays, "tinylace_fnet_conv1_bias", NULL, NULL,"tinylace_fnet_conv1_weights_float", NULL, NULL, NULL, 113, 16)) return 1;
    if (linear_init(&model->lace_fnet_conv2, arrays, "tinylace_fnet_conv2_bias", "tinylace_fnet_conv2_subias", "tinylace_fnet_conv2_weights_int8","tinylace_fnet_conv2_weights_float", NULL, NULL, "tinylace_fnet_conv2_scale", 128, 16)) return 1;
    if (linear_init(&model->lace_fnet_tconv, arrays, "tinylace_fnet_tconv_bias", "tinylace_fnet_tconv_subias", "tinylace_fnet_tconv_weights_int8","tinylace_fnet_tconv_weights_float", NULL, NULL, "tinylace_fnet_tconv_scale", 16, 64)) return 1;
    if (linear_init(&model->lace_fnet_gru_input, arrays, "tinylace_fnet_gru_input_bias", "tinylace_fnet_gru_input_subias", "tinylace_fnet_gru_input_weights_int8","tinylace_fnet_gru_input_weights_float", NULL, NULL, "tinylace_fnet_gru_input_scale", 16, 48)) return 1;
    if (linear_init(&model->lace_fnet_gru_recurrent, arrays, "tinylace_fnet_gru_recurrent_bias", "tinylace_fnet_gru_recurrent_subias", "tinylace_fnet_gru_recurrent_weights_int8","tinylace_fnet_gru_recurrent_weights_float", NULL, NULL, "tinylace_fnet_gru_recurrent_scale", 16, 48)) return 1;
    if (linear_init(&model->lace_cf1_kernel, arrays, "tinylace_cf1_kernel_bias", "tinylace_cf1_kernel_subias", "tinylace_cf1_kernel_weights_int8","tinylace_cf1_kernel_weights_float", NULL, NULL, "tinylace_cf1_kernel_scale", 16, 16)) return 1;
    if (linear_init(&model->lace_cf1_gain, arrays, "tinylace_cf1_gain_bias", NULL, NULL,"tinylace_cf1_gain_weights_float", NULL, NULL, NULL, 16, 1)) return 1;
    if (linear_init(&model->lace_cf1_global_gain, arrays, "tinylace_cf1_global_gain_bias", NULL, NULL,"tinylace_cf1_global_gain_weights_float", NULL, NULL, NULL, 16, 1)) return 1;
    if (linear_init(&model->lace_cf2_kernel, arrays, "tinylace_cf2_kernel_bias", "tinylace_cf2_kernel_subias", "tinylace_cf2_kernel_weights_int8","tinylace_cf2_kernel_weights_float", NULL, NULL, "tinylace_cf2_kernel_scale", 16, 16)) return 1;
    if (linear_init(&model->lace_cf2_gain, arrays, "tinylace_cf2_gain_bias", NULL, NULL,"tinylace_cf2_gain_weights_float", NULL, NULL, NULL, 16, 1)) return 1;
    if (linear_init(&model->lace_cf2_global_gain, arrays, "tinylace_cf2_global_gain_bias", NULL, NULL,"tinylace_cf2_global_gain_weights_float", NULL, NULL, NULL, 16, 1)) return 1;
    if (linear_init(&model->lace_af1_kernel, arrays, "tinylace_af1_kernel_bias", "tinylace_af1_kernel_subias", "tinylace_af1_kernel_weights_int8","tinylace_af1_kernel_weights_float", NULL, NULL, "tinylace_af1_kernel_scale", 16, 16)) return 1;
    if (linear_init(&model->lace_af1_gain, arrays, "tinylace_af1_gain_bias", NULL, NULL,"tinylace_af1_gain_weights_float", NULL, NULL, NULL, 16, 1)) return 1;
    return 0;
}
#endif /* DUMP_BINARY_WEIGHTS */
